{"operation":"run_python","code":"import math

def primes_up_to(N):
    sieve = [True] * (N + 1)
    for i in range(2, int(N**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, N + 1, i):
                sieve[j] = False
    return [i for i in range(2, N + 1) if sieve[i]]

def get_primes(n):
    # We need up to p_n. By PNT, p_n ~ n log n. Let's overestimate by 2*n*log(n+1).
    if n < 6:
        limit = 15
    else:
        limit = int(2 * n * math.log(n + 1))
    return primes_up_to(limit)[:n]

def solve(n):
    primes = get_primes(n)
    p_n = primes[-1]

    # Numerator: sum_{n < p <= p_n} log(p/(p-1))
    num = 0.0
    for p in primes:
        if p > n and p <= p_n:
            num += math.log(p / (p - 1))

    # Denominator: log( pi(n) * m_n / (phi(m_n) * n) )
    # m_n = product of first n primes
    m_n = 1
    phi_m_n = 1
    for p in primes:
        m_n *= p
        phi_m_n *= (p - 1)

    pi_n = sum(1 for p in primes if p <= n) # wait, primes list only goes up to p_n. We need all primes <= n.
    # Let's just count properly.
    all_primes = primes_up_to(n)
    pi_n = len(all_primes)

    denom = math.log((pi_n * m_n) / (phi_m_n * n))

    return num, denom, num/denom

for n in [10, 20, 50, 100, 200, 500, 1000]:
    num, denom, ratio = solve(n)
    print(f"n={n}: num={num:.6f}, denom={denom:.6f}, ratio={ratio:.6f}")
"}

