def f(x):
    return x**x

def get_derivative(n, x):
    # Use mpmath.diff
    return mpmath.diff(f, x, n)

roots = {}
for n in range(1, 21):
    # We want to find the largest root of f^(n)(x) = 0 for x > 0.
    # Let's scan from x=0.01 to x=100 to find sign changes.
    xs = [0.01 * (i+1) for i in range(10000)]
    signs = []
    for x in xs:
        try:
            val = get_derivative(n, x)
            if mpmath.isnan(val) or mpmath.isinf(val):
                signs.append(0)
            else:
                signs.append(1 if val > 0 else -1)
        except:
            signs.append(0)

    # Find intervals where sign changes
    roots_n = []
    for i in range(len(xs)-1):
        if signs[i] == 0:
            roots_n.append(xs[i])
        elif signs[i] * signs[i+1] < 0:
            try:
                r = mpmath.findroot(lambda t: get_derivative(n, t), (xs[i], xs[i+1]))
                roots_n.append(r)
            except:
                pass

    if roots_n:
        max_root = max(roots_n)
        roots[n] = max_root
        print(f"n={n}, max root = {max_root}")
